import java.util.*;

public class KvSim {
    record Version(String value, Map<String, Integer> clock) {
        public String toString() { return value + clock; }
    }

    static boolean descends(Map<String, Integer> a, Map<String, Integer> b) {   // a >= b
        for (var e : b.entrySet()) if (a.getOrDefault(e.getKey(), 0) < e.getValue()) return false;
        return true;
    }

    /** Drop versions that are dominated by another version. */
    static List<Version> reconcile(Collection<Version> all) {
        List<Version> out = new ArrayList<>();
        for (Version v : all) {
            boolean dominated = false;
            for (Version o : all) {
                if (o != v && descends(o.clock(), v.clock()) && !o.clock().equals(v.clock())) {
                    dominated = true;
                }
            }
            if (!dominated && out.stream().noneMatch(x -> x.clock().equals(v.clock()))) out.add(v);
        }
        return out;
    }

    static class Node {
        final String name; boolean up = true;
        final Map<String, List<Version>> data = new HashMap<>();
        final List<Object[]> hints = new ArrayList<>();         // {targetName, key, version}
        Node(String name) { this.name = name; }
        void store(String key, Version v) {
            List<Version> cur = new ArrayList<>(data.getOrDefault(key, List.of()));
            cur.add(v);
            data.put(key, reconcile(cur));
        }
    }

    final int n = 3;
    final Map<String, Node> nodes = new LinkedHashMap<>();
    final TreeMap<Integer, String> ring = new TreeMap<>();

    KvSim(String... names) {
        for (String s : names) {
            nodes.put(s, new Node(s));
            for (int v = 0; v < 8; v++) ring.put(hash(s + "#" + v), s);
    }
}

static int hash(String s) {
    int h = 0x811C9DC5;
    for (char c : s.toCharArray()) { h ^= c; h *= 0x01000193; }
    h ^= h >>> 15; h *= 0x2C1B3C6D; h ^= h >>> 12;
    return h;
}

/** Distinct physical nodes clockwise from the key position; first n are the preference list. */
List<String> walk(String key) {
    List<String> out = new ArrayList<>();
    var tail = ring.tailMap(hash(key), true).values();
    for (String s : tail) if (!out.contains(s)) out.add(s);
    for (String s : ring.values()) if (!out.contains(s)) out.add(s);
    return out;
}

/** Sloppy-quorum write. Returns acks. Coordinator = first live node of the preference list. */
int put(String key, String value, Map<String, Integer> ctx, int w, Set<String> unreachable) {
    List<String> walk = walk(key);
    List<String> pref = walk.subList(0, n);
    String coord = pref.stream().filter(s -> nodes.get(s).up).findFirst().orElseThrow();
    Map<String, Integer> clock = new TreeMap<>(ctx);
    clock.merge(coord, 1, Integer::sum);
    Version v = new Version(value, clock);
    int acks = 0, spare = n;
    for (String target : pref) {
        if (nodes.get(target).up && !unreachable.contains(target)) {
            nodes.get(target).store(key, v); acks++;
        } else {                                    // stand-in node holds a hint
            while (spare < walk.size() && (!nodes.get(walk.get(spare)).up
                    || unreachable.contains(walk.get(spare)))) spare++;
            if (spare < walk.size()) {
                Node s = nodes.get(walk.get(spare++));
                s.hints.add(new Object[] {target, key, v});
                acks++;
                System.out.println("    hint for " + target + " stored on " + s.name);
            }
        }
    }
    System.out.println("  put " + key + "=" + value + " coordinator=" + coord + " acks=" + acks
        + (acks >= w ? " (W=" + w + " met)" : " (W=" + w + " NOT met)"));
    return acks;
}

List<Version> get(String key, int r, Set<String> unreachable) {
    List<Version> seen = new ArrayList<>();
    int asked = 0;
    for (String s : walk(key).subList(0, n)) {
        Node nd = nodes.get(s);
        if (!nd.up || unreachable.contains(s) || asked == r) continue;
        asked++;
        seen.addAll(nd.data.getOrDefault(key, List.of()));
    }
    return reconcile(seen);
}

void handoff() {
    for (Node s : nodes.values()) {
        if (!s.up) continue;
        Iterator<Object[]> it = s.hints.iterator();
        while (it.hasNext()) {
            Object[] h = it.next();
            Node target = nodes.get((String) h[0]);
            if (target.up) {
                target.store((String) h[1], (Version) h[2]);
                it.remove();
                System.out.println("    handoff of " + h[1] + " from " + s.name
                    + " to " + target.name);
            }
        }
    }
}
    public static void main(String[] args) {
        KvSim kv = new KvSim("A", "B", "C", "D", "E");
        String key = "cart:42";
        System.out.println("preference list for " + key + " = " + kv.walk(key).subList(0, 3)
            + ", stand-in nodes = " + kv.walk(key).subList(3, 5));
        Set<String> none = Set.of();

        System.out.println("1) normal write and read (N=3, W=2, R=2)");
        kv.put(key, "[book]", Map.of(), 2, none);
        System.out.println("  get -> " + kv.get(key, 2, none));

        String down = kv.walk(key).get(1);
        System.out.println("2) replica " + down + " is down: sloppy quorum and hinted handoff");
        kv.nodes.get(down).up = false;
        List<Version> cur = kv.get(key, 2, none);
        kv.put(key, "[book, pen]", cur.get(0).clock(), 2, none);
        kv.nodes.get(down).up = true;
        System.out.println("  " + down + " is back, stale copy = "
            + kv.nodes.get(down).data.get(key));
        kv.handoff();
        System.out.println("  " + down + " after handoff = " + kv.nodes.get(down).data.get(key));

        System.out.println("3) concurrent writers on both sides of a partition");
        List<String> pref = kv.walk(key).subList(0, 3);
        Map<String, Integer> base = kv.get(key, 2, none).get(0).clock();
        Set<String> sideA = Set.of(pref.get(1), pref.get(2));     // writer 1 sees only pref[0]
        kv.put(key, "[book, pen, lamp]", base, 1, sideA);
        Set<String> sideB = Set.of(pref.get(0));                   // writer 2: first node down
        kv.nodes.get(pref.get(0)).up = false;
        kv.put(key, "[book, pen, mug]", base, 1, sideB);
        kv.nodes.get(pref.get(0)).up = true;
        List<Version> siblings = kv.get(key, 3, none);
        System.out.println("  read after heal returns " + siblings.size()
            + " siblings: " + siblings);
        Map<String, Integer> merged = new TreeMap<>();
        for (Version v : siblings) v.clock().forEach((k, c) -> merged.merge(k, c, Math::max));
        kv.put(key, "[book, pen, lamp, mug]", merged, 2, none);
        System.out.println("  after client merge -> " + kv.get(key, 3, none));

        System.out.println("4) why R + W > N matters: W=1 write reaching only one replica");
        String k2 = "profile:7";
        List<String> p2 = kv.walk(k2).subList(0, 3);
        kv.put(k2, "v1", Map.of(), 3, none);
        Node n1 = kv.nodes.get(p2.get(0));
        Version v2 = new Version("v2", new TreeMap<>(Map.of(p2.get(0), 2)));
        n1.store(k2, v2);
        System.out.println("  only " + p2.get(0) + " holds v2; replicas "
            + p2.subList(1, 3) + " hold v1");
        System.out.println("  R=1 reading from " + p2.get(2) + " only -> "
            + kv.get(k2, 1, Set.of(p2.get(0), p2.get(1))));
        System.out.println("  R=2 over " + p2.get(0) + "," + p2.get(1) + " -> "
            + kv.get(k2, 2, Set.of(p2.get(2))));
        System.out.println("  R=3 -> " + kv.get(k2, 3, none));
    }
}

import java.util.ArrayList;
import java.util.List;

public class ClusterSlots {
    /** CRC16 XMODEM (polynomial 0x1021, initial value 0), the variant used by Redis Cluster. */
    static int crc16(byte[] data) {
        int crc = 0;
        for (byte b : data) {
            crc ^= (b & 0xFF) << 8;
        for (int i = 0; i < 8; i++) {
            crc = ((crc & 0x8000) != 0) ? ((crc << 1) ^ 0x1021) : (crc << 1);
            crc &= 0xFFFF;
        }
    }
    return crc;
}

/** Slot of a key; only the text inside the first non-empty {...} is hashed. */
static int slot(String key) {
    int open = key.indexOf('{');
    if (open >= 0) {
        int close = key.indexOf('}', open + 1);
        if (close > open + 1) key = key.substring(open + 1, close);
    }
    return crc16(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)) % 16384;
}

/** Contiguous slot ranges, one per node. */
static int[] ownerBySlot(int nodes) {
    int[] owner = new int[16384];
    for (int s = 0; s < 16384; s++) owner[s] = (int) ((long) s * nodes / 16384);
    return owner;
}

public static void main(String[] args) {
    System.out.printf("crc16(\"123456789\") = 0x%04X (XMODEM check value is 0x31C3)%n",
        crc16("123456789".getBytes()));
    for (String k : new String[] {"foo", "bar", "user:1000", "{user:1000}.cart",
                                  "{user:1000}.orders", "foo{}{bar}"}) {
        System.out.printf("slot(%-20s) = %d%n", "\"" + k + "\"", slot(k));
    }
    int[] three = ownerBySlot(3);
    System.out.println("3 masters: node0 owns slots 0.."
        + lastSlot(three, 0) + ", node1 owns " + firstSlot(three, 1) + ".." + lastSlot(three, 1)
        + ", node2 owns " + firstSlot(three, 2) + "..16383");

    // growth from 3 to 4 masters with 1,000,000 keys
    int keys = 1_000_000;
    int[] four = ownerBySlot(4);
    long movedSlotsOnly = 0;
    long movedModulo = 0;
    for (int i = 0; i < keys; i++) {
        int s = slot("item:" + i);
        if (three[s] != four[s]) movedSlotsOnly++;
    }
    for (int i = 0; i < keys; i++) {
        int h = ("item:" + i).hashCode() & 0x7FFFFFFF;
        if (h % 3 != h % 4) movedModulo++;
    }
    System.out.printf("3 -> 4 nodes, equal contiguous re-split: %d moved (%.1f%%)%n",
        movedSlotsOnly, 100.0 * movedSlotsOnly / keys);
    // minimal migration: each old master hands over only what it holds above 4096 slots
    int[] minimal = three.clone();
    int[] count = new int[4];
    for (int o : three) count[o]++;
    int[] surplus = {count[0] - 4096, count[1] - 4096, count[2] - 4096};
    for (int s = 0; s < 16384; s++) {
        int o = three[s];
        if (surplus[o] > 0) { surplus[o]--; minimal[s] = 3; count[o]--; count[3]++; }
    }
    long movedMin = 0;
    for (int i = 0; i < keys; i++) {
        int s = slot("item:" + i);
        if (three[s] != minimal[s]) movedMin++;
    }
    System.out.printf("3 -> 4 nodes, only surplus slots: %d moved (%.1f%%), per node %s%n",
        movedMin, 100.0 * movedMin / keys, java.util.Arrays.toString(count));
    System.out.printf("3 -> 4 nodes with hash(key) mod N: %d moved (%.1f%%)%n",
        movedModulo, 100.0 * movedModulo / keys);
}

static int firstSlot(int[] o, int n) {
    for (int s = 0; s < o.length; s++) if (o[s] == n) return s;
    return -1;
    }

    static int lastSlot(int[] o, int n) {
        for (int s = o.length - 1; s >= 0; s--) if (o[s] == n) return s;
        return -1;
    }
}

import java.util.*;

public class NotifySim {
    enum Priority { HIGH, NORMAL, LOW }

    static final class Msg {
        final String id, dedupKey; final Priority prio; final int createdAt;
        int readyAt, attempts;
        Msg(String id, String dedupKey, Priority prio, int createdAt) {
            this.id = id; this.dedupKey = dedupKey; this.prio = prio;
            this.createdAt = createdAt; this.readyAt = createdAt;
        }
    }

    static final int CAPACITY = 50;             // provider accepts 50 messages per second
    static final double FAIL = 0.20;            // transient provider error rate
    static final int MAX_ATTEMPTS = 5;

    static void run(String mode, boolean priorityAware) {
        Random rnd = new Random(42);
        Comparator<Msg> order = priorityAware
            ? Comparator.<Msg>comparingInt(m -> m.prio.ordinal()).thenComparingInt(m -> m.readyAt)
            : Comparator.<Msg>comparingInt(m -> m.readyAt).thenComparing(m -> m.id);
        PriorityQueue<Msg> ready = new PriorityQueue<>(order);
        List<Msg> waiting = new ArrayList<>();           // retry timers
        Set<String> seen = new HashSet<>();
        List<Integer> highLatency = new ArrayList<>();
        int suppressed = 0, delivered = 0, dead = 0, retries = 0;

        List<Msg> incoming = new ArrayList<>();
        for (int i = 0; i < 2000; i++) {
            incoming.add(new Msg("promo-" + i, "promo:" + i, Priority.LOW, 0));
        }
        for (int s = 0; s < 10; s++)
            for (int i = 0; i < 2; i++)
                incoming.add(new Msg("otp-" + s + "-" + i, "otp:" + s + ":" + i, Priority.HIGH, s));
        for (int i = 0; i < 30; i++)                     // duplicate submissions of existing promos
            incoming.add(new Msg("promo-dup-" + i, "promo:" + i, Priority.LOW, 1));

        int t = 0;
        while (t < 200 && (t < 10 || !ready.isEmpty() || !waiting.isEmpty())) {
            for (Msg m : incoming) {
                if (m.createdAt == t) {
                    if (seen.add(m.dedupKey)) ready.add(m); else suppressed++;
                }
            }
            Iterator<Msg> it = waiting.iterator();
            while (it.hasNext()) {
                Msg m = it.next();
                if (m.readyAt <= t) { it.remove(); ready.add(m); }
            }
            for (int slot = 0; slot < CAPACITY && !ready.isEmpty(); slot++) {
                Msg m = ready.poll();
                m.attempts++;
                if (rnd.nextDouble() < FAIL) {
                    if (m.attempts >= MAX_ATTEMPTS) { dead++; continue; }
                    // exponential backoff with full jitter: uniform in (0, 2^attempts] seconds
                    int backoff = (int) Math.ceil(rnd.nextDouble() * (1 << m.attempts));
                    m.readyAt = t + backoff;
                    waiting.add(m);
                    retries++;
                } else {
                    delivered++;
                    if (m.prio == Priority.HIGH) highLatency.add(t - m.createdAt);
                }
            }
            t++;
        }
        Collections.sort(highLatency);
        System.out.printf("%-26s delivered=%d retries=%d dead=%d duplicates suppressed=%d%n",
            mode, delivered, retries, dead, suppressed);
        System.out.printf("%-26s OTP latency (s): p50=%d max=%d; queue empty at t=%d s%n", "",
            highLatency.get(highLatency.size() / 2), highLatency.get(highLatency.size() - 1), t);
    }

    public static void main(String[] args) {
        System.out.println("2000 promotional + 20 OTP messages + 30 duplicate submissions;");
        System.out.println("provider limit 50/s, 20% transient failures");
        run("single FIFO queue", false);
        run("priority queues (HIGH first)", true);
        double p = Math.pow(FAIL, MAX_ATTEMPTS);
        System.out.printf("probability that one message fails all %d attempts = %.5f%n",
            MAX_ATTEMPTS, p);
    }
}

