import java.util.*;

public class SchedSim {
    enum State { READY, LEASED, DONE }

    static final class Job {
        final String id; final int runAt; State state = State.READY;
        int leaseUntil, attempts; long fence;            // fence: increases on every lease
        Job(String id, int runAt) { this.id = id; this.runAt = runAt; }
    }

    /** Stands in for a table polled with FOR UPDATE SKIP LOCKED; synchronized = atomic. */
    static final class JobStore {
        final Map<String, Job> jobs = new LinkedHashMap<>();
        long fenceCounter = 0; final int leaseSeconds;
        JobStore(int leaseSeconds) { this.leaseSeconds = leaseSeconds; }

        synchronized Job lease(int now) {
            for (Job j : jobs.values()) {
                boolean due = j.state == State.READY && j.runAt <= now;
                boolean expired = j.state == State.LEASED && j.leaseUntil <= now;
                if (due || expired) {
                    j.state = State.LEASED; j.leaseUntil = now + leaseSeconds;
                    j.attempts++; j.fence = ++fenceCounter;
                    return j;
                }
            }
            return null;
        }

        synchronized boolean complete(String id, long fence) {   // conditional update
            Job j = jobs.get(id);
            if (j.state != State.LEASED || j.fence != fence) return false;
            j.state = State.DONE;
            return true;
        }
    }

    record Running(Job job, long fence, int finishAt) {}

    public static void main(String[] args) {
        JobStore store = new JobStore(10);
        for (int i = 1; i <= 4; i++) store.jobs.put("job-" + i, new Job("job-" + i, i * 2));
        Set<String> sideEffects = new LinkedHashSet<>();     // idempotent effect keyed by job id
        int duplicateEffects = 0;
        // worker behaviour: w1 healthy (3 s per job); w2 crashes at t=7; w3 is slow (14 s) on job-4
        Map<String, Running> busy = new HashMap<>();
        boolean w2Dead = false;
        for (int t = 0; t <= 40; t++) {
            if (t == 7 && busy.containsKey("w2")) {
                System.out.printf("t=%2d  w2 crashes while running %s%n", t,
                    busy.remove("w2").job().id);
                w2Dead = true;
            }
            for (String w : List.of("w1", "w2", "w3")) {
                Running r = busy.get(w);
                if (r != null && r.finishAt() <= t) {
                    busy.remove(w);
                    boolean first = sideEffects.add(r.job().id);
                    if (!first) duplicateEffects++;
                    boolean ok = store.complete(r.job().id, r.fence());
                    System.out.printf("t=%2d  %s finished %s (fence %d): %s%s%n", t, w,
                        r.job().id, r.fence(), ok ? "accepted" : "REJECTED (stale fence)",
                        first ? "" : "; effect already applied, skipped");
                }
                if (busy.containsKey(w) || (w.equals("w2") && w2Dead)) continue;
                Job j = store.lease(t);
                if (j == null) continue;
                int duration = w.equals("w3") ? 14 : 3;
                busy.put(w, new Running(j, j.fence, t + duration));
                System.out.printf("t=%2d  %s leased %s attempt=%d fence=%d lease until t=%d%n",
                    t, w, j.id, j.attempts, j.fence, j.leaseUntil);
            }
        }
        System.out.println("final states:");
        for (Job j : store.jobs.values()) {
            System.out.println("  " + j.id + " " + j.state + " attempts=" + j.attempts);
        }
        System.out.println("distinct side effects=" + sideEffects.size()
            + ", executions that were repeats=" + duplicateEffects);

        // recurring job: next fire time on a fixed interval, skipping missed runs after downtime
        int interval = 900, last = 3600, now = 3600 + 4 * 900 + 120;
        int next = last + ((now - last) / interval + 1) * interval;
        System.out.println("interval 900 s, last fired at 3600, restart at " + now
            + " -> next fire at " + next
            + " (skipped " + ((next - last) / interval - 1) + ")");
    }
}

import java.util.*;

public class FanoutSim {
    public static void main(String[] args) {
        final int users = 100_000, follows = 50;
        Random rnd = new Random(42);
        // popularity weight ~ power law: weight of rank r is r^-0.8
        double[] cum = new double[users];
        double sum = 0;
        for (int r = 0; r < users; r++) { sum += Math.pow(r + 1, -0.8); cum[r] = sum; }
        int[] followers = new int[users];
        int[][] followees = new int[users][];
        for (int u = 0; u < users; u++) {
            Set<Integer> set = new HashSet<>();
            while (set.size() < follows) {
                int v = lowerBound(cum, rnd.nextDouble() * sum);
                if (v != u) set.add(v);
            }
            followees[u] = set.stream().mapToInt(Integer::intValue).toArray();
            for (int v : followees[u]) followers[v]++;
        }
        int max = Arrays.stream(followers).max().getAsInt();
        long edges = (long) users * follows;
        System.out.printf("users=%d follows/user=%d edges=%d max followers=%d%n",
            users, follows, edges, max);
        System.out.println("strategy              inserts/day (1 post each)  lookups per read");
        System.out.printf("fan-out on write      %,12d             %d%n", edges, 1);
        System.out.printf("fan-out on read       %,12d             %d%n", (long) users, follows);
        for (int threshold : new int[] {1000, 5000, 20000}) {
            long writes = 0;
            for (int v = 0; v < users; v++) writes += followers[v] <= threshold ? followers[v] : 0;
            long celebLookups = 0; int celebs = 0;
            for (int v = 0; v < users; v++) if (followers[v] > threshold) celebs++;
            for (int u = 0; u < users; u++)
                for (int v : followees[u]) if (followers[v] > threshold) celebLookups++;
            double perRead = 1 + (double) celebLookups / users;
            System.out.printf("hybrid T=%-6d       %,12d             %.2f   (celebrities=%d)%n",
                threshold, writes, perRead, celebs);
        }
    }

    static int lowerBound(double[] a, double x) {
        int lo = 0, hi = a.length - 1;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] < x) lo = m + 1; else hi = m; }
        return lo;
    }
}

import java.util.*;

public class ChatSim {
    record Msg(String conv, long seq, String clientMsgId, String body) {}

    /** Server side: one sequencer per conversation; deduplicates by client message id. */
    static class Sequencer {
        private final Map<String, Long> next = new HashMap<>();
        private final Map<String, Msg> byClientId = new HashMap<>();
        Msg accept(String conv, String clientMsgId, String body) {
            Msg dup = byClientId.get(conv + "/" + clientMsgId);
            if (dup != null) return dup;                    // retry of an already stored message
            long seq = next.merge(conv, 1L, Long::sum);
            Msg m = new Msg(conv, seq, clientMsgId, body);
            byClientId.put(conv + "/" + clientMsgId, m);
            return m;
        }
    }

    /** Client side: delivers strictly in sequence order, buffers gaps, ignores duplicates. */
    static class Receiver {
        long lastShown = 0;
        final TreeMap<Long, Msg> pending = new TreeMap<>();
        final List<String> shown = new ArrayList<>();
        void onMessage(Msg m) {
            if (m.seq() <= lastShown || pending.containsKey(m.seq())) {
                shown.add("  (drop duplicate seq " + m.seq() + ")");
                return;
            }
            pending.put(m.seq(), m);
            while (!pending.isEmpty() && pending.firstKey() == lastShown + 1) {
                Msg n = pending.pollFirstEntry().getValue();
                lastShown = n.seq();
                shown.add("show seq " + n.seq() + ": " + n.body());
            }
        }
        long gapFrom() { return pending.isEmpty() ? -1 : lastShown + 1; }
    }

    public static void main(String[] args) {
        Sequencer server = new Sequencer();
        String conv = "c42";
        Msg a = server.accept(conv, "u1-001", "hello");
        Msg b = server.accept(conv, "u2-001", "hi, are you there?");
        Msg c = server.accept(conv, "u1-002", "meeting at 10");
        Msg retry = server.accept(conv, "u1-002", "meeting at 10");   // client retry
        System.out.println("retry returns same seq: " + (retry.seq() == c.seq())
            + " (seq " + retry.seq() + ")");

        Receiver r = new Receiver();
        // network reorders and duplicates: c, a, a, b
        for (Msg m : List.of(c, a, a, b)) {
            r.onMessage(m);
            System.out.println("arrive seq " + m.seq() + " -> pending=" + r.pending.keySet()
                + " lastShown=" + r.lastShown);
        }
        r.shown.forEach(System.out::println);

        Receiver lossy = new Receiver();
        lossy.onMessage(a);
        lossy.onMessage(c);                                           // seq 2 lost
        System.out.println("gap detected, client requests sync from seq " + lossy.gapFrom());
        lossy.onMessage(b);                                           // resync delivers seq 2
        System.out.println("after resync lastShown=" + lossy.lastShown
            + " pending=" + lossy.pending.keySet());
    }
}

import java.util.*;

public class NearbyDrivers {
    static final String BASE32 = "0123456789bcdefghjkmnpqrstuvwxyz";
    static final int PRECISION = 6;                       // 30 bits: 15 lon, 15 lat
    static final double LAT_STEP = 180.0 / (1 << 15);     // about 0.61 km
    static final double LON_STEP = 360.0 / (1 << 15);     // about 1.19 km at 13 degrees latitude

    static String geohash(double lat, double lon) {
        double latLo = -90, latHi = 90, lonLo = -180, lonHi = 180;
        StringBuilder sb = new StringBuilder();
        boolean evenBit = true;
        int bit = 0, ch = 0;
        while (sb.length() < PRECISION) {
            if (evenBit) {
                double mid = (lonLo + lonHi) / 2;
                if (lon >= mid) { ch = (ch << 1) | 1; lonLo = mid; } else { ch <<= 1; lonHi = mid; }
            } else {
                double mid = (latLo + latHi) / 2;
                if (lat >= mid) { ch = (ch << 1) | 1; latLo = mid; } else { ch <<= 1; latHi = mid; }
            }
            evenBit = !evenBit;
            if (++bit == 5) { sb.append(BASE32.charAt(ch)); bit = 0; ch = 0; }
        }
        return sb.toString();
    }

    static double km(double lat1, double lon1, double lat2, double lon2) {   // haversine
        double dLat = Math.toRadians(lat2 - lat1), dLon = Math.toRadians(lon2 - lon1);
        double a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(Math.toRadians(lat1))
            * Math.cos(Math.toRadians(lat2)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
        return 6371.0 * 2 * Math.asin(Math.sqrt(a));
    }

    record Driver(int id, double lat, double lon) {}

    public static void main(String[] args) {
        Random rnd = new Random(7);
        double lat0 = 12.97, lon0 = 77.59;                // city centre; box of about 40 km x 40 km
        List<Driver> all = new ArrayList<>();
        Map<String, List<Driver>> index = new HashMap<>();
        for (int i = 0; i < 100_000; i++) {
            double lat = lat0 + (rnd.nextDouble() - 0.5) * 0.36;
            double lon = lon0 + (rnd.nextDouble() - 0.5) * 0.36;
            Driver d = new Driver(i, lat, lon);
            all.add(d);
            index.computeIfAbsent(geohash(lat, lon), k -> new ArrayList<>()).add(d);
        }
        System.out.println("drivers=" + all.size() + " non-empty cells=" + index.size()
            + " avg per cell=" + String.format("%.1f", all.size() / (double) index.size()));
        System.out.println("rider cell " + geohash(lat0, lon0) + ", cell about 1.19 km x 0.61 km");

        double radiusKm = 1.5;
        int rows = (int) Math.ceil(radiusKm / 0.61), cols = (int) Math.ceil(radiusKm / 1.19);
        int queries = 1000;
        long examined = 0, mismatches = 0, found = 0;
        long tGrid = 0, tBrute = 0;
        for (int q = 0; q < queries; q++) {
            double lat = lat0 + (rnd.nextDouble() - 0.5) * 0.30;
            double lon = lon0 + (rnd.nextDouble() - 0.5) * 0.30;
            long t0 = System.nanoTime();
            Set<Integer> viaGrid = new TreeSet<>();
            for (int dr = -rows; dr <= rows; dr++) {
                for (int dc = -cols; dc <= cols; dc++) {
                    String key = geohash(lat + dr * LAT_STEP, lon + dc * LON_STEP);
                    List<Driver> cell = index.get(key);
                    if (cell == null) continue;
                    for (Driver d : cell) {
                        examined++;
                        if (km(lat, lon, d.lat(), d.lon()) <= radiusKm) viaGrid.add(d.id());
                    }
                }
            }
            long t1 = System.nanoTime();
            Set<Integer> viaScan = new TreeSet<>();
            for (Driver d : all) {
                if (km(lat, lon, d.lat(), d.lon()) <= radiusKm) viaScan.add(d.id());
            }
            long t2 = System.nanoTime();
            tGrid += t1 - t0; tBrute += t2 - t1;
            if (!viaGrid.equals(viaScan)) mismatches++;
            found += viaScan.size();
        }
        System.out.printf("queries=%d radius=%.1f km cells per query=%d%n", queries, radiusKm,
            (2 * rows + 1) * (2 * cols + 1));
        System.out.printf("avg drivers inside radius=%.1f%n", found / (double) queries);
        System.out.printf("grid examined per query=%.0f vs brute force=%d%n",
            examined / (double) queries, all.size());
        System.out.println("result mismatches vs brute force=" + mismatches);
        System.out.printf("avg time per query: grid=%.3f ms brute=%.3f ms (typical)%n",
            tGrid / 1e6 / queries, tBrute / 1e6 / queries);
    }
}

