import java.util.*;

public class SeatHolds {
    enum State { AVAILABLE, HELD, PAYMENT_PENDING, SOLD }

    static class Seat {
        State state = State.AVAILABLE;
        String owner;
        long expiresAt;                    // virtual clock, seconds
    }

    static final Map<String, Seat> seats = new TreeMap<>();
    static long now = 0;
    static final long HOLD_TTL = 600, PAYMENT_GRACE = 300;

    /** A seat is takeable if available or if its hold has expired (lazy expiry). */
    static synchronized boolean hold(String seatId, String user) {
        Seat s = seats.get(seatId);
        boolean free = s.state == State.AVAILABLE
            || ((s.state == State.HELD || s.state == State.PAYMENT_PENDING) && s.expiresAt <= now);
        if (!free) return false;
        s.state = State.HELD; s.owner = user; s.expiresAt = now + HOLD_TTL;
        return true;
    }

    /** Payment started: extend the hold so that the gateway has time to answer. */
    static synchronized boolean startPayment(String seatId, String user) {
        Seat s = seats.get(seatId);
        if (s.state != State.HELD || !user.equals(s.owner) || s.expiresAt <= now) return false;
        s.state = State.PAYMENT_PENDING; s.expiresAt = now + PAYMENT_GRACE;
        return true;
    }

    /** Payment succeeded: confirm only if this user still holds the seat. */
    static synchronized boolean confirm(String seatId, String user) {
        Seat s = seats.get(seatId);
        boolean ok = (s.state == State.PAYMENT_PENDING || s.state == State.HELD)
            && user.equals(s.owner) && s.expiresAt > now;
        if (ok) s.state = State.SOLD;
        return ok;
    }

    static void log(String msg) { System.out.printf("t=%4ds  %s%n", now, msg); }

    public static void main(String[] args) {
        seats.put("A1", new Seat());
        seats.put("B7", new Seat());
        log("alice holds A1: " + hold("A1", "alice"));
        log("bob tries A1: " + hold("A1", "bob") + " (held by alice)");
        now = 590;
        log("alice starts payment: " + startPayment("A1", "alice")
            + ", hold now ends at t=" + seats.get("A1").expiresAt);
        now = 700;
        log("bob tries A1 during payment: " + hold("A1", "bob"));
        now = 880;
        log("gateway answers, confirm(alice): " + confirm("A1", "alice"));
        now = 1000;
        log("carol holds B7: " + hold("B7", "carol"));
        now = 1700;
        log("carol's payment succeeds at t=1700, hold ended at t=1600: "
            + confirm("B7", "carol") + " -> refund required");
        log("dave holds B7 (expired hold is reusable): " + hold("B7", "dave"));
        seats.forEach((id, s) -> log(id + " -> " + s.state + " owner=" + s.owner));
    }
}

UPDATE stock SET reserved = reserved + :qty
 WHERE sku = :sku AND bucket = :bucket AND on_hand - reserved >= :qty;
-- one row updated: reserved; zero rows: insufficient stock in this bucket

import java.util.*;

public class CheckoutSaga {
    static class Inventory {
        final Map<String, Integer> available = new HashMap<>(Map.of("sku-1", 2));
        final Map<String, Integer> reservations = new HashMap<>();          // orderId -> quantity
        boolean reserve(String orderId, String sku, int qty) {
            if (reservations.containsKey(orderId)) return true;             // idempotent on orderId
            if (available.get(sku) < qty) return false;
            available.merge(sku, -qty, Integer::sum);
            reservations.put(orderId, qty);
            return true;
        }
        void release(String orderId, String sku) {
            Integer q = reservations.remove(orderId);
            if (q != null) available.merge(sku, q, Integer::sum);
        }
    }

    static class Payments {
        final Map<String, String> byIdempotencyKey = new HashMap<>();
        int authorizations = 0;
        int dropReplies = 0;                      // lost replies: work done, answer not delivered
        boolean declineNext = false;
        String authorize(String key, int cents) {
            String done = byIdempotencyKey.get(key);
            if (done != null) return done;        // same key: return the stored result
            String result;
            if (declineNext) result = "DECLINED"; else { authorizations++; result = "AUTHORIZED"; }
            byIdempotencyKey.put(key, result);
            if (dropReplies-- > 0) throw new RuntimeException("timeout");
            return result;
        }
        void voidAuth(String key) { byIdempotencyKey.put(key, "VOIDED"); }
    }

    static String checkout(String orderId, Inventory inv, Payments pay) {
        List<String> log = new ArrayList<>();
        log.add("order " + orderId + " PENDING");
        if (!inv.reserve(orderId, "sku-1", 1)) return "CANCELLED (out of stock)";
        log.add("inventory reserved");
        String result = null;
        for (int attempt = 1; attempt <= 3 && result == null; attempt++) {
            try {
                result = pay.authorize("pay-" + orderId, 4999);
            } catch (RuntimeException e) {
                log.add("payment try " + attempt + " failed: " + e.getMessage());
            }
        }
        if (!"AUTHORIZED".equals(result)) {
            inv.release(orderId, "sku-1");
            log.add("compensation: inventory released");
            System.out.println("  " + String.join(" -> ", log));
            return "CANCELLED (" + result + ")";
        }
        log.add("payment authorized");
        System.out.println("  " + String.join(" -> ", log));
        return "CONFIRMED";
    }
    public static void main(String[] args) {
        Inventory inv = new Inventory();
        Payments pay = new Payments();
        System.out.println("1. normal order");
        System.out.println("  result: " + checkout("o1", inv, pay) + ", stock=" + inv.available);
        System.out.println("2. card declined");
        pay.declineNext = true;
        System.out.println("  result: " + checkout("o2", inv, pay) + ", stock=" + inv.available);
        pay.declineNext = false;
        System.out.println("3. first payment reply lost, orchestrator retries with the same key");
        pay.dropReplies = 1;
        System.out.println("  result: " + checkout("o3", inv, pay) + ", stock=" + inv.available
            + ", total authorizations=" + pay.authorizations + " (o1 and o3)");
        System.out.println("4. stock exhausted");
        System.out.println("  result: " + checkout("o4", inv, pay) + ", stock=" + inv.available);
    }
}

import java.util.*;

public class TrieAutocomplete {
    static final int K = 5;

    record Entry(String query, long count) {}

    static class Node {
        final Map<Character, Node> next = new TreeMap<>();
        final List<Entry> top = new ArrayList<>();          // best K completions under this prefix
    }

    final Node root = new Node();

    /** Insert or update one query; every node on its path refreshes its top-K list: O(L * K). */
    void update(String q, long newCount) {
        Node n = root;
        offer(n, q, newCount);
        for (char c : q.toCharArray()) {
            n = n.next.computeIfAbsent(c, k -> new Node());
            offer(n, q, newCount);
        }
    }

    private static void offer(Node n, String q, long count) {
        n.top.removeIf(e -> e.query().equals(q));
        n.top.add(new Entry(q, count));
        n.top.sort((a, b) -> b.count() != a.count() ? Long.compare(b.count(), a.count())
                                                    : a.query().compareTo(b.query()));
        while (n.top.size() > K) n.top.remove(n.top.size() - 1);
    }

    List<Entry> suggest(String prefix) {
        Node n = root;
        for (char c : prefix.toCharArray()) {
            n = n.next.get(c);
            if (n == null) return List.of();
        }
        return n.top;
    }

    static List<Entry> bruteForce(Map<String, Long> counts, String prefix) {
        List<Entry> all = new ArrayList<>();
        for (var e : counts.entrySet()) {
            if (e.getKey().startsWith(prefix)) all.add(new Entry(e.getKey(), e.getValue()));
        }
        all.sort((a, b) -> b.count() != a.count() ? Long.compare(b.count(), a.count())
                                                  : a.query().compareTo(b.query()));
        return all.subList(0, Math.min(K, all.size()));
    }

    public static void main(String[] args) {
        // synthetic vocabulary: 2,000 pronounceable words, Zipf-like popularity
        Random rnd = new Random(1);
        String[] syl = {"ba", "ko", "ri", "tu", "men", "sa", "lo", "vi", "ne", "pra", "do",
            "chi", "an", "el", "or"};
        List<String> words = new ArrayList<>();
        while (words.size() < 2000) {
            StringBuilder sb = new StringBuilder();
            int n = 2 + rnd.nextInt(3);
            for (int i = 0; i < n; i++) sb.append(syl[rnd.nextInt(syl.length)]);
            if (!words.contains(sb.toString())) words.add(sb.toString());
        }
        Map<String, Long> counts = new HashMap<>();
        for (int i = 0; i < 300_000; i++) {
            int w1 = (int) Math.min(1999, Math.abs(rnd.nextGaussian()) * 350);   // skewed
            String q = words.get(w1) + (rnd.nextInt(3) == 0 ? " " + words.get((int) Math.min(1999,
                Math.abs(rnd.nextGaussian()) * 350)) : "");
            counts.merge(q, 1L + rnd.nextInt(20), Long::sum);
        }
        TrieAutocomplete t = new TrieAutocomplete();
        long t0 = System.nanoTime();
        counts.forEach(t::update);
        long build = System.nanoTime() - t0;
        System.out.printf("distinct queries=%d, build time=%.0f ms (typical)%n",
            counts.size(), build / 1e6);

        String p = words.get(0).substring(0, 2);
        System.out.println("suggest(\"" + p + "\"):");
        for (Entry e : t.suggest(p)) System.out.println("  " + e.query() + "  " + e.count());

        int checked = 0, mismatches = 0;
        long tTrie = 0, tScan = 0;
        for (String q : counts.keySet()) {
            if (checked >= 2000) break;
            String prefix = q.substring(0, 1 + rnd.nextInt(Math.min(4, q.length())));
            long a = System.nanoTime();
            List<Entry> fast = t.suggest(prefix);
            long b = System.nanoTime();
            List<Entry> slow = bruteForce(counts, prefix);
            long c = System.nanoTime();
            tTrie += b - a; tScan += c - b;
            if (!fast.equals(slow)) mismatches++;
            checked++;
        }
        System.out.printf("prefixes checked=%d mismatches=%d%n", checked, mismatches);
        System.out.printf("avg lookup: trie=%.1f us, scan of all queries=%.0f us (typical)%n",
            tTrie / 1e3 / checked, tScan / 1e3 / checked);

        String hot = words.get(1500);
        String pre = hot.substring(0, 3);
        System.out.println("before: top for \"" + pre + "\" = " + t.suggest(pre).get(0));
        t.update(hot, 1_000_000);                                   // trending query appears
        System.out.println("after:  top for \"" + pre + "\" = " + t.suggest(pre).get(0));
    }
}

import java.security.MessageDigest;
import java.util.*;

public class ChunkDemo {
    static final int FIXED = 64 * 1024;
    static final int MIN = 16 * 1024, MAX = 256 * 1024;
    static final long MASK = (1L << 16) - 1;                 // boundary probability 1/65536
    static final long[] GEAR = new long[256];
    static { Random r = new Random(99); for (int i = 0; i < 256; i++) GEAR[i] = r.nextLong(); }

    static List<byte[]> fixed(byte[] d) {
        List<byte[]> out = new ArrayList<>();
        for (int i = 0; i < d.length; i += FIXED) {
            out.add(Arrays.copyOfRange(d, i, Math.min(d.length, i + FIXED)));
        }
        return out;
    }

    /** Content-defined chunking (gear rolling hash): boundaries depend on content, not offsets. */
    static List<byte[]> cdc(byte[] d) {
        List<byte[]> out = new ArrayList<>();
        int start = 0;
        long h = 0;
        for (int i = 0; i < d.length; i++) {
            h = (h << 1) + GEAR[d[i] & 0xFF];
            int len = i - start + 1;
            if ((len >= MIN && (h & MASK) == 0) || len >= MAX) {
                out.add(Arrays.copyOfRange(d, start, i + 1));
                start = i + 1;
                h = 0;
            }
        }
        if (start < d.length) out.add(Arrays.copyOfRange(d, start, d.length));
        return out;
    }

    static String sha(byte[] c) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(c));
    }

    static Set<String> hashes(List<byte[]> chunks) throws Exception {
        Set<String> s = new HashSet<>();
        for (byte[] c : chunks) s.add(sha(c));
        return s;
    }

    static void report(String edit, byte[] oldData, byte[] newData) throws Exception {
        for (String mode : new String[] {"fixed 64 KiB", "content-defined"}) {
            boolean fx = mode.startsWith("fixed");
            List<byte[]> oc = fx ? fixed(oldData) : cdc(oldData);
            List<byte[]> nc = fx ? fixed(newData) : cdc(newData);
            Set<String> known = hashes(oc);
            long upload = 0; int changed = 0;
            for (byte[] c : nc) {
                if (!known.contains(sha(c))) { changed++; upload += c.length; }
            }
            System.out.printf("%-28s %-16s chunks=%3d upload=%3d chunks %8d B (%.1f%%)%n",
                edit, mode, nc.size(), changed, upload, 100.0 * upload / newData.length);
        }
    }

    static byte[] random(int n, long seed) {
        byte[] b = new byte[n];
        new Random(seed).nextBytes(b);
        return b;
    }

    public static void main(String[] args) throws Exception {
        byte[] base = random(8 * 1024 * 1024, 5);
        byte[] patch = random(100, 6);
        byte[] ins = new byte[base.length + 100];              // 100 bytes inserted near the start
        System.arraycopy(base, 0, ins, 0, 1000);
        System.arraycopy(patch, 0, ins, 1000, 100);
        System.arraycopy(base, 1000, ins, 1100, base.length - 1000);
        byte[] over = base.clone();                            // 100 bytes overwritten
        System.arraycopy(patch, 0, over, 4_000_000, 100);
        byte[] app = Arrays.copyOf(base, base.length + 1024 * 1024);    // 1 MiB appended
        System.arraycopy(random(1024 * 1024, 7), 0, app, base.length, 1024 * 1024);
        System.out.println("file: 8 MiB; chunks: fixed 64 KiB vs content-defined (16..256 KiB)");
        report("insert 100 B at offset 1000", base, ins);
        report("overwrite 100 B at 4 MB", base, over);
        report("append 1 MiB", base, app);
    }
}

DROP TABLE IF EXISTS ledger_entries, transfers, accounts CASCADE;
DROP FUNCTION IF EXISTS transfer_ordered, transfer_naive;
CREATE TABLE accounts (
  account_id int PRIMARY KEY,
  balance    bigint NOT NULL CHECK (balance >= 0)     -- cached; the ledger is the truth
);
CREATE TABLE transfers (
  idem_key   int PRIMARY KEY,                         -- idempotency key from the client
  src int NOT NULL, dst int NOT NULL, amount bigint NOT NULL,
  status     text NOT NULL
);
CREATE TABLE ledger_entries (
  entry_id   bigserial PRIMARY KEY,
  idem_key   int NOT NULL REFERENCES transfers,
  account_id int NOT NULL REFERENCES accounts,
  amount     bigint NOT NULL                          -- signed: debit < 0, credit > 0
);
INSERT INTO accounts SELECT g, 1000 FROM generate_series(1, 4) g;

CREATE FUNCTION transfer_ordered(k int, a int, b int, amt bigint) RETURNS text AS $$
DECLARE bal bigint;
BEGIN
  INSERT INTO transfers VALUES (k, a, b, amt, 'PENDING') ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN RETURN 'duplicate'; END IF;   -- a retry: the stored result stands
  IF a = b THEN
    UPDATE transfers SET status = 'REJECTED' WHERE idem_key = k;
    RETURN 'rejected';
  END IF;
  PERFORM 1 FROM accounts WHERE account_id IN (a, b)
   ORDER BY account_id FOR UPDATE;                -- canonical lock order
  SELECT balance INTO bal FROM accounts WHERE account_id = a;
  IF bal < amt THEN
    UPDATE transfers SET status = 'REJECTED' WHERE idem_key = k;
    RETURN 'rejected';
  END IF;
  INSERT INTO ledger_entries(idem_key, account_id, amount) VALUES (k, a, -amt), (k, b, amt);
  UPDATE accounts SET balance = balance - amt WHERE account_id = a;
  UPDATE accounts SET balance = balance + amt WHERE account_id = b;
  UPDATE transfers SET status = 'OK' WHERE idem_key = k;
  RETURN 'ok';
END $$ LANGUAGE plpgsql;

CREATE FUNCTION transfer_naive(k int, a int, b int, amt bigint) RETURNS text AS $$
DECLARE bal bigint;
BEGIN
  INSERT INTO transfers VALUES (k, a, b, amt, 'PENDING') ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN RETURN 'duplicate'; END IF;
  IF a = b THEN
    UPDATE transfers SET status = 'REJECTED' WHERE idem_key = k;
    RETURN 'rejected';
  END IF;
  SELECT balance INTO bal FROM accounts WHERE account_id = a FOR UPDATE;   -- source first
  PERFORM pg_sleep(0.002);
  PERFORM 1 FROM accounts WHERE account_id = b FOR UPDATE;                 -- then destination
  IF bal < amt THEN
    UPDATE transfers SET status = 'REJECTED' WHERE idem_key = k;
    RETURN 'rejected';
  END IF;
  INSERT INTO ledger_entries(idem_key, account_id, amount) VALUES (k, a, -amt), (k, b, amt);
  UPDATE accounts SET balance = balance - amt WHERE account_id = a;
  UPDATE accounts SET balance = balance + amt WHERE account_id = b;
  UPDATE transfers SET status = 'OK' WHERE idem_key = k;
  RETURN 'ok';
END $$ LANGUAGE plpgsql;
